// Construct this token at runtime: Vite transforms literal import-meta URLs even
// inside generated-source strings. Exported files must not capture build paths.
const localModuleURL = ["import", "meta", "url"].join(".");
// Fixed local tools, never generated by AI. The exported website needs no JS.
export const VERIFY_SCRIPT = String.raw`import {readFile,readdir,lstat,realpath} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {resolve} from 'node:path';
const root=new URL('../',${localModuleURL});
const names=['.node-version','README.md','index.html','manifest.json','package-lock.json','package.json','scripts/serve.mjs','scripts/verify.mjs','styles.css'];
const sha=value=>createHash('sha256').update(value).digest('hex');
function canonical(value){if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).sort().map(key=>JSON.stringify(key)+':'+canonical(value[key])).join(',')+'}';return JSON.stringify(value);}
export async function verify(){
  if(process.versions.node!=='24.19.0')throw new Error('Use Node.js 24.19.0, conforme .node-version');
  const found=[];
  async function walk(prefix=''){
    for(const name of await readdir(new URL(prefix,root))){
      const path=prefix+name,info=await lstat(new URL(path,root));
      if(info.isSymbolicLink())throw new Error('Symlink recusado');
      if(info.isDirectory()){if(path!=='scripts')throw new Error('Diretório inesperado');await walk(path+'/');}
      else if(info.isFile()&&names.includes(path)&&info.size<=1048576)found.push(path);
      else throw new Error('Arquivo inesperado ou grande demais');
    }
  }
  await walk();if(found.sort().join('|')!==names.join('|'))throw new Error('Inventário incompleto');
  const files=new Map();let total=0;for(const name of names){const bytes=await readFile(new URL(name,root));total+=bytes.length;if(total>2097152)throw new Error('Limite total excedido');files.set(name,bytes);}
  const manifest=JSON.parse(files.get('manifest.json').toString('utf8'));
  const {artifact_sha256,...descriptor}=manifest;
  if(manifest.schema_version!==1||manifest.profile!=='studio-static-v1'||sha(canonical(descriptor))!==artifact_sha256)throw new Error('Manifesto inválido');
  if(!Array.isArray(manifest.files)||manifest.files.length!==names.length-1)throw new Error('Inventário inválido');
  const listed=manifest.files.map(file=>file.path);
  if(listed.join('|')!==names.filter(name=>name!=='manifest.json').join('|'))throw new Error('Nomes inválidos');
  for(const file of manifest.files){const bytes=files.get(file.path);if(bytes.length!==file.bytes||sha(bytes)!==file.sha256)throw new Error('Integridade inválida: '+file.path);}
  const html=files.get('index.html').toString('utf8'),body=html.match(/<body[\s\S]*<\/body>/)?.[0],head=html.split('<meta http-equiv="Content-Security-Policy"')[0];
  if(!body||sha(JSON.stringify([head,body,files.get('styles.css').toString('utf8')]))!==manifest.visual_sha256)throw new Error('Prévia e pacote não correspondem');
  return files;
}
if(process.argv[1]&&await realpath(resolve(process.argv[1]))===fileURLToPath(${localModuleURL})){await verify();console.log('Manifesto e arquivos conferidos.');}
`;
export const SERVE_SCRIPT = String.raw`import {createServer} from 'node:http';
import {verify} from './verify.mjs';
const files=await verify();
const policy="default-src 'none'; script-src 'none'; style-src 'self'; style-src-attr 'none'; img-src 'none'; font-src 'none'; connect-src 'none'; object-src 'none'; frame-src 'none'; media-src 'none'; worker-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";
const routes=new Map([['/','index.html'],['/index.html','index.html'],['/styles.css','styles.css']]);
createServer((request,response)=>{
  if(!['127.0.0.1:4173','localhost:4173'].includes(request.headers.host)){response.writeHead(421);response.end();return;}
  if(!['GET','HEAD'].includes(request.method)){response.writeHead(405,{Allow:'GET, HEAD'});response.end();return;}
  const file=routes.get(new URL(request.url,'http://127.0.0.1:4173').pathname);
  if(!file){response.writeHead(404);response.end();return;}
  const body=files.get(file);
  response.writeHead(200,{'Content-Type':file.endsWith('.css')?'text/css; charset=utf-8':'text/html; charset=utf-8','Content-Length':body.length,'Content-Security-Policy':policy,'Referrer-Policy':'no-referrer','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','X-Frame-Options':'DENY'});
  response.end(request.method==='HEAD'?undefined:body);
}).listen(4173,'127.0.0.1',()=>console.log('Site local: http://127.0.0.1:4173 (Ctrl+C para encerrar).'));
`;
export const EXPORT_README = `# Site estático revisado

Este projeto contém HTML/CSS controlados, equivalentes ao corpo e aos estilos da prévia selecionada no Creative Studio. Não há JavaScript no navegador, imagens, fontes remotas, serviços externos, segredos ou dependências de terceiros.

## Executar sem instalar dependências

Use Node.js 24.19.0 (versão fixada em .node-version; npm 11.9.0 quando utilizar npm).

1. Confira o conteúdo dos scripts locais controlados.
2. Execute: node scripts/verify.mjs
3. Execute: node scripts/serve.mjs
4. Abra http://127.0.0.1:4173. Use Ctrl+C para encerrar.

Alternativas equivalentes: npm run verify e npm start. Não é necessário npm install ou npm ci. Não abra index.html por file://: a política de segurança foi preparada para HTTP local.

## Escopo

As páginas usam fragmentos locais e CSS, como a prévia. Links externos/contatos permanecem inativos. Nenhum conteúdo de briefing privado, snapshot, observação interna, chave ou identidade do revisor é incluído. O JSON bruto de origem não é exportado para evitar destinos e metadados que a prévia não mostra.

manifest.json informa versão do site, hash original do documento, perfil do renderizador, tamanhos e SHA-256 de todos os demais arquivos. O campo artifact_sha256 protege a estrutura canônica do manifesto, sem incluir a si mesmo. O manifesto não é uma assinatura digital; não autentica um pacote recebido de terceiros que tenham reescrito também o manifesto. A origem deve ser conferida no Studio/download autorizado.

Os arquivos já são o código-fonte estático; não há compilação nem download de ferramentas. Modificações manuais invalidam os hashes e a revisão original. O servidor verifica os arquivos e os mantém em memória, serve somente HTML/CSS e escuta apenas em loopback. Não é servidor de produção.

Publicação, hospedagem, ativação de links, assets, SEO por rota e alterações exigem revisão e configuração futuras. Este ZIP não publica nada, não comprova veracidade/licenças/acessibilidade e não autoriza automaticamente uso público em qualquer contexto.
`;
